def build_dataset():
    entries = []
    today = "2026-10-28"
    
    for idx, (word, ipa, vn, cat, ex, ex_vi) in enumerate(RAW_GOETHE_A1, start=1):
        entries.append({
            "id": idx,
            "german": word,
            "french": word, # backward compatibility
            "ipa": ipa,
            "vietnamese": vn,
            "category": cat,
            "example": ex,
            "exampleVi": ex_vi,
            "repetition": 0,
            "interval": 0,
            "easeFactor": 2.5,
            "dueDate": today,
            "mistakes": 0
        })
    
    dest1 = os.path.join("src", "data", "vocab_goethe_a1.json")
    dest2 = os.path.join("src", "data", "vocab_a0_a1.json")
    
    with open(dest1, "w", encoding="utf-8") as f:
        json.dump(entries, f, ensure_ascii=False, indent=2)
        
    with open(dest2, "w", encoding="utf-8") as f:
        json.dump(entries, f, ensure_ascii=False, indent=2)
        
    print(f"Successfully generated {len(entries)} Goethe-Zertifikat A1 words to {dest1} and {dest2}")

if __name__ == "__main__":
    build_dataset()
